<?php declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use AteEducacion\CanariasRouteMatrix\Reader; use AteEducacion\CanariasRouteMatrix\Exception\{CrossIslandRouteException,UnknownCenterException,UnreachableRouteException};
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: public, max-age=300');header('Access-Control-Allow-Origin: '.(getenv('CORS_ORIGIN')?:'*'));$cid=$_SERVER['HTTP_X_CORRELATION_ID']??bin2hex(random_bytes(8));header('X-Correlation-ID: '.$cid);
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);$method=$_SERVER['REQUEST_METHOD']??'GET';$binary=getenv('MATRIX_BINARY')?:dirname(__DIR__,2).'/data/samples/sample.bin';
try{$reader=new Reader($binary);if($method==='GET'&&$path==='/v1/health'){$body=['status'=>'ok'];}elseif($method==='GET'&&$path==='/v1/version'){$body=['format'=>'CEDIST01','api_version'=>'v1'];}elseif($method==='GET'&&preg_match('#^/v1/routes/([0-9]{8})/([0-9]{8})$#D',$path,$m)){$r=$reader->getRoute($m[1],$m[2]);$body=['origin'=>['code'=>$m[1]],'destination'=>['code'=>$m[2]],'distance_m'=>$r->distanceMeters,'duration_s'=>$r->durationSeconds];}else{http_response_code(404);$body=['error'=>['code'=>'not_found','message'=>'Endpoint not found']];}}
catch(UnknownCenterException $e){http_response_code(404);$body=['error'=>['code'=>'unknown_center','message'=>$e->getMessage()]];}catch(CrossIslandRouteException|UnreachableRouteException $e){http_response_code(422);$body=['error'=>['code'=>'route_unavailable','message'=>$e->getMessage()]];}catch(Throwable $e){http_response_code(503);$body=['error'=>['code'=>'artifact_unavailable','message'=>'Route artifact unavailable']];error_log(json_encode(['correlation_id'=>$cid,'error'=>get_class($e)]));}echo json_encode($body,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
